```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

const MOD = 1000000007;

rl.on('line', (line) => {
    const [nStr, pStr] = line.trim().split(' ');
    const n = parseInt(nStr, 10);
    const p = parseInt(pStr, 10);

    const maxL = p - 1;
    if (maxL <= 0) {
        console.log(0);
        rl.close();
        return;
    }

    const grundy = new Array(maxL + 1).fill(0);
    // grundy[0] is unused, index is length L = r - l
    // L=1 -> g=0, L=2 -> g=0
    if (maxL >= 1) grundy[1] = 0;
    if (maxL >= 2) grundy[2] = 0;

    for (let L = 3; L <= maxL; L++) {
        const k = Math.floor(L / 2);
        const L1 = k;
        const L2 = L - k;
        const g1 = grundy[L1];
        const g2 = grundy[L2];
        if (g1 !== 0 && g2 !== 0) {
            grundy[L] = 0;
        } else if (g1 !== 1 && g2 !== 1) {
            grundy[L] = 1;
        } else {
            grundy[L] = 2;
        }
    }

    const count = [0, 0, 0];
    for (let L = 1; L <= maxL; L++) {
        const g = grundy[L];
        const ways = p - L;
        count[g] = (count[g] + ways) % MOD;
    }

    const c0 = count[0];
    const c1 = count[1];
    const c2 = count[2];

    // DP for number of sequences of length n with XOR sum v
    // dp[v] = number of ways for current length
    let dp = [1, 0, 0, 0]; // length 0
    for (let i = 0; i < n; i++) {
        const next = [0, 0, 0, 0];
        for (let v = 0; v < 4; v++) {
            if (dp[v] === 0) continue;
            // add g=0
            next[v] = (next[v] + dp[v] * c0) % MOD;
            // add g=1
            next[v ^ 1] = (next[v ^ 1] + dp[v] * c1) % MOD;
            // add g=2
            next[v ^ 2] = (next[v ^ 2] + dp[v] * c2) % MOD;
        }
        dp = next;
    }

    const ans = (dp[1] + dp[2] + dp[3]) % MOD;
    console.log(ans);
    rl.close();
});
